// packages/data/repositories/historicoRepository.js
import { BaseRepository } from './_baseRepo.js';
export class HistoricoRepository extends BaseRepository {
    constructor() {
        super('historico', { defaultOrderBy: 'dataHora', filterableColumns: ['usuarioID', 'catalogoID', 'tipo', 'acao'] });
    }
    // Histórico é imutável
    update()     { throw new Error('Registros históricos não podem ser alterados.'); }
    softDelete() { throw new Error('Registros históricos não podem ser excluídos.'); }
    hardDelete() { throw new Error('Registros históricos não podem ser excluídos.'); }
}